        unsigned int Fb_Flg_1                               : 6 ;  // Hdaudio data is from/to framebuffer select 1: frame buffer0: not in frame buffer [0] : frame buffer select for STRM2 DMA postion request [1] : frame buffer select for STRM3 DMA postion request [2] : frame buffer select for STRM0 BDL request [3] : frame buffer select for STRM1 BDL request [4] : frame buffer select for STRM0 DATA request [5] : frame buffer select for STRM1 DATA request
        unsigned int Reserved_1                             : 2 ;
